mapper.select:
select t.shop_id shopId, t.shop_num shopNum, t.location_id locationId, t.location_name locationName,
       t.built_up_area builtUpArea, t.shop_area shopArea, t.remark,
       t.state, t.community_id communityId, t.shop_rent shopRent, t.status_cd statusCd,
       o.owner_id ownerId, o.owner_name ownerName, o.link, o.start_time startTime, o.end_time endTime,
       t.create_time createTime
from building_shop t
left join building_shop_owner o on t.shop_id = o.shop_id and o.status_cd = '0'
where 1 = 1
and t.status_cd = '0'

    and t.shop_id = #{shopId}


    and t.shop_id in

        #{item}



    and t.shop_num like concat('%', #{shopNum}, '%')


    and t.location_id = #{locationId}


    and o.owner_id = #{ownerId}


    and o.owner_name like concat('%', #{ownerName}, '%')


    and o.link like concat('%', #{link}, '%')


    and o.create_time >= #{rentTimeStart}


    and o.create_time <= #{rentTimeEnd}


    and t.state = #{state}


    and t.community_id = #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

select count(1) count
from building_shop t
left join building_shop_owner o on t.shop_id = o.shop_id and o.status_cd = '0'
where 1 = 1 and t.status_cd = '0'

    and t.shop_id = #{shopId}


    and t.shop_num like concat('%', #{shopNum}, '%')


    and t.location_id = #{locationId}


    and o.owner_id = #{ownerId}


    and o.owner_name like concat('%', #{ownerName}, '%')


    and o.link like concat('%', #{link}, '%')


    and o.create_time >= #{rentTimeStart}


    and o.create_time <= #{rentTimeEnd}


    and t.state = #{state}


    and t.community_id = #{communityId}

mapper.update:
update building_shop t set t.status_cd = #{statusCd}

    , t.shop_num = #{shopNum}


    , t.location_id = #{locationId}


    , t.location_name = #{locationName}


    , t.built_up_area = #{builtUpArea}


    , t.shop_area = #{shopArea}


    , t.remark = #{remark}


    , t.state = #{state}


    , t.shop_rent = #{shopRent}

where 1 = 1

    and t.shop_id = #{shopId}


    and t.community_id = #{communityId}
